      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README_EN.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\"\n  ],\n  \"license\": \"MIT\",\n  \"devDependencies\": {\n    \"@types/node\": \"^26.2.0\",\n    \"esbuild\": \"^0.28.2\",\n    \"typescript\": \"^7.0.2\"\n  }\n}\n"
